{
  "findings": [
    {
      "check_id": "CKV_GCP_37",
      "title": "Ensure VM disks for critical VMs are encrypted with Customer Supplied Encryption Keys (CSEK)",
      "resource": "google_compute_disk.changeme_count_attached_disk_disk",
      "severity": "MEDIUM",
      "explanation": "The disk resource does not specify a customer-supplied encryption key (CSEK). Without CSEK, the disk relies on Google-managed encryption keys, which may not meet stricter compliance or security requirements."
    }
  ],
  "patched_code": "resource \"google_compute_disk\" \"changeme_count_attached_disk_disk\" {\n  name                      = \"changeme-count-attached-disk-disk-${count.index}\"\n  count                     = var.changeme_google_attached_disk_count_number_of_instances\n  type                      = \"pd-ssd\"\n  zone                      = \"us-central1-a\"\n  size                      = 4\n  physical_block_size_bytes = 4096\n\n  disk_encryption_key {\n    kms_key_self_link = var.kms_key_self_link\n  }\n}",
  "fix_summary": "Added a `disk_encryption_key` block to specify a customer-supplied encryption key (CSEK) for the disk, ensuring compliance with CKV_GCP_37."
}
